const prisma = new PrismaClient({
  adapter: new PrismaPg({ connectionString: url }),
});

class Rollback extends Error {}

async function main() {
  const creator = await prisma.creator.findFirstOrThrow();

  // 1. Read the balance inside a Serializable transaction, write a probe row,
  //    then abort. This is the shape feature 6's payout commit will use.
  try {
    await prisma.$transaction(
      async (tx) => {
        const isolation = await tx.$queryRawUnsafe<{ transaction_isolation: string }[]>(
          "SHOW transaction_isolation",
        );
        console.log("isolation inside tx:", isolation[0]?.transaction_isolation);

        const available = await tx.ledgerEntry.aggregate({
          where: { creatorId: creator.id, type: { not: "EARNING_PENDING" } },
          _sum: { amountMinor: true },
        });
        console.log("available read inside tx:", available._sum.amountMinor);

        await tx.ledgerEntry.create({
          data: {
            creatorId: creator.id,
            type: "ADJUSTMENT",
            amountMinor: 1,
            description: "probe row, rolled back",
          },
        });
        console.log("probe row written inside tx");
        throw new Rollback();
      },
      { isolationLevel: "Serializable", timeout: 15_000 },
    );
  } catch (error) {
    if (!(error instanceof Rollback)) throw error;
    console.log("rollback: ok");
  }

  console.log("ledger rows after rollback:", await prisma.ledgerEntry.count(), "(expect 11)");

  // 2. Same shape, but committing, to prove a Serializable write survives the pooler.
  await prisma.$transaction(
    async (tx) => {
      const entry = await tx.ledgerEntry.create({
        data: {
          creatorId: creator.id,
          type: "ADJUSTMENT",
          amountMinor: 1,
          description: "probe row, committed then removed",
        },
      });
      console.log("committed probe row id:", entry.id.slice(0, 8));
    },
    { isolationLevel: "Serializable", timeout: 15_000 },
  );
  const committed = await prisma.ledgerEntry.count();
  console.log("ledger rows after commit:", committed, "(expect 12)");

  await prisma.ledgerEntry.deleteMany({
    where: { description: "probe row, committed then removed" },
  });
  console.log("ledger rows after cleanup:", await prisma.ledgerEntry.count(), "(expect 11)");
}

main()
  .catch((e) => { console.error("FAILED:", e); process.exitCode = 1; })
  .finally(() => prisma.$disconnect());
